Register handlers for all APIs in this module in the supplied `Router` instance.

Paramerets:
- `router`: Router to register handlers in
- `impl`: module that implements the server methods

Optional parameters:
- `path_prefix`: prefix to be applied to all paths
- `optional_middlewares`: Register one or more optional middlewares to be applied to all requests.

Optional middlewares can be one or more of:
    - `init`: called before the request is processed
    - `pre_validation`: called after the request is parsed but before validation
    - `pre_invoke`: called after validation but before the handler is invoked
    - `post_invoke`: called after the handler is invoked but before the response is sent

The order in which middlewares are invoked are:
`init |> read |> pre_validation |> validate |> pre_invoke |> invoke |> post_invoke`
"""
function register(router::HTTP.Router, impl; path_prefix::String="", optional_middlewares...)
    registerAssistantsApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerAudioApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerAuditLogsApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerBatchApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerChatApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerCompletionsApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerDefaultApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerEmbeddingsApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerFilesApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerFineTuningApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerImagesApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerInvitesApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerModelsApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerModerationsApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerProjectsApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerRealtimeApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerUploadsApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerUsageApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerUsersApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerVectorStoresApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    return router
end

end # module APIServer
